window.MAPS = (window.MAPS||[]).concat([
{ cat:"Communication & British Culture", type:"Expressions", lvl:"A2", icon:"👋", t:"Greetings & Small Talk", es:"Saludos y charla informal", d:"Cómo saludar y conversar de forma ligera, al estilo británico.",
 boxes:[
  {e:"🙋", h:"Saying hello", es:"Saludos habituales", i:[["Hello / Hi","Hola"],["Morning!","¡Buenos días! (informal)"],["Good afternoon","Buenas tardes (más formal)"]], ex:["Morning! Lovely day, isn't it?","¡Buenos días! Qué día tan agradable, ¿verdad?"]},
  {e:"🤝", h:"You alright?", es:"El saludo británico típico", i:[["You alright?","¿Qué tal? (no es una pregunta real)"],["Alright, mate?","¿Qué pasa, amigo?"],["How do you do?","Mucho gusto (muy formal)"]], ex:["Hiya! You alright?","¡Hola! ¿Qué tal?"]},
  {e:"💬", h:"Replying", es:"Cómo responder", i:[["Not bad, thanks. You?","No va mal, gracias. ¿Y tú?"],["Fine, cheers.","Bien, gracias."],["Can't complain.","No me quejo."]], ex:["Not bad, thanks. And yourself?","No está mal, gracias. ¿Y tú?"]},
  {e:"☔", h:"Talking about the weather", es:"El tema estrella", i:[["Nice weather, isn't it?","Buen tiempo, ¿verdad?"],["It's a bit chilly.","Hace algo de fresco."],["Typical British weather!","¡Típico tiempo británico!"]], ex:["It's absolutely pouring, isn't it?","Está lloviendo a cántaros, ¿verdad?"]},
  {e:"🗣️", h:"Keeping it going", es:"Mantener la charla", i:[["Have you been busy?","¿Has estado ocupado?"],["Do anything nice at the weekend?","¿Hiciste algo agradable el fin de semana?"],["How's work?","¿Cómo va el trabajo?"]], ex:["Have you been up to anything interesting lately?","¿Has hecho algo interesante últimamente?"]},
  {e:"👋", h:"Saying goodbye", es:"Despedirse", i:[["See you later / Cheerio","Hasta luego"],["Take care","Cuídate"],["Right, I'd better get going.","Bueno, tengo que irme."]], ex:["Lovely to see you. Take care!","Un placer verte. ¡Cuídate!"]}
 ], qs:[
  {q:"Choose the best reply: 'You alright?' – (a) 'Not bad, thanks. You?' (b) 'Yes, I am alright, thank you for asking about my health.'", a:"(a) — 'You alright?' es un saludo; responde corto y devuelve la pregunta."},
  {q:"Fill the gap: '____ weather, isn't it?' (Nice / Good morning)", a:"Nice — 'Nice weather, isn't it?' abre una charla típica británica."},
  {q:"Rewrite more naturally: 'I must leave now.' (Right, I'd ...)", a:"Right, I'd better get going. — más natural y suave para despedirse."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"A2", icon:"🧑‍🤝‍🧑", t:"Introducing Yourself & Others", es:"Presentarse y presentar a otros", d:"Frases para presentarte y presentar a alguien con naturalidad.",
 boxes:[
  {e:"🙂", h:"Introducing yourself", es:"Presentarte", i:[["I'm Ana, nice to meet you.","Soy Ana, encantada."],["My name's Carlos.","Me llamo Carlos."],["I'm from Madrid, in Spain.","Soy de Madrid, en España."]], ex:["Hi, I'm Ana. I'm here for the course.","Hola, soy Ana. Vengo por el curso."]},
  {e:"🤝", h:"Introducing someone", es:"Presentar a alguien", i:[["This is my friend, Tom.","Este es mi amigo Tom."],["Let me introduce you to Sarah.","Deja que te presente a Sarah."],["Have you met Jo?","¿Conoces a Jo?"]], ex:["Have you two met? This is Tom.","¿Ya se conocen? Este es Tom."]},
  {e:"💼", h:"Formal introductions", es:"Presentaciones formales", i:[["May I introduce Mr Green?","Permítame presentarle al Sr. Green."],["Pleased to meet you.","Encantado de conocerle."],["How do you do?","Mucho gusto (la respuesta es la misma frase)"]], ex:["Pleased to meet you, Dr Brown.","Encantado de conocerle, Dr. Brown."]},
  {e:"🗨️", h:"Replying to an introduction", es:"Responder", i:[["Nice to meet you too.","Igualmente, un placer."],["Lovely to meet you.","Encantado de conocerte."],["I've heard a lot about you.","He oído hablar mucho de ti."]], ex:["Lovely to meet you. I've heard a lot about you.","Encantada. He oído hablar mucho de ti."]},
  {e:"📋", h:"Giving background", es:"Hablar de ti", i:[["I work as a nurse.","Trabajo de enfermera."],["I'm studying English at university.","Estudio inglés en la universidad."],["I live in Leeds.","Vivo en Leeds."]], ex:["I work for the NHS in Manchester.","Trabajo para el NHS en Mánchester."]},
  {e:"⚠️", h:"Tips for Spanish speakers", es:"Consejos para hispanohablantes", i:[["I'm 25 (not 'I have 25')","Tengo 25 años (se usa 'be')"],["I'm a teacher (with 'a')","Soy profesor (en inglés lleva 'a')"],["Shake hands, don't kiss","Apretón de manos, no besos"]], ex:["I'm 30 and I'm an engineer.","Tengo 30 años y soy ingeniero."]}
 ], qs:[
  {q:"Correct it: 'I have 28 years.'", a:"I'm 28 (years old). — En inglés se usa 'be', no 'have'."},
  {q:"Choose the best reply to 'How do you do?' – (a) 'Fine, thanks.' (b) 'How do you do?'", a:"(b) — es una fórmula muy formal; se responde con la misma frase."},
  {q:"Rewrite more formally: 'This is my boss, Mr Hill.' (May I ...)", a:"May I introduce my boss, Mr Hill? — presentación formal."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"A2", icon:"🙏", t:"Polite Requests", es:"Pedir cosas con educación", d:"Cómo pedir favores de forma amable, como lo hacen los británicos.",
 boxes:[
  {e:"🙋", h:"Could you...?", es:"¿Podrías...?", i:[["Could you pass the salt, please?","¿Me pasas la sal, por favor?"],["Would you mind + -ing?","¿Te importaría...?"]], ex:["Would you mind opening the window?","¿Te importaría abrir la ventana?"]},
  {e:"🧸", h:"Softening phrases", es:"Suavizar la petición", i:[["I was wondering if you could...","Me preguntaba si podrías..."],["Sorry to bother you, but...","Perdona la molestia, pero..."],["Excuse me, could I just...","Disculpa, ¿podría...?"]], ex:["Sorry to bother you, but could you help me?","Perdona la molestia, pero ¿podrías ayudarme?"]},
  {e:"❓", h:"Indirect questions", es:"Preguntas indirectas", i:[["Do you know where the toilets are?","¿Sabes dónde están los baños?"],["Could you tell me what time it is?","¿Podría decirme qué hora es?"]], ex:["Could you tell me where the station is?","¿Podría decirme dónde está la estación?"]},
  {e:"✅", h:"Saying yes", es:"Aceptar una petición", i:[["Of course.","Por supuesto."],["Certainly.","Claro (formal)."],["No problem at all.","Ningún problema."]], ex:["Of course. Here you are.","Por supuesto. Aquí tienes."]},
  {e:"🙇", h:"Saying no politely", es:"Rechazar con tacto", i:[["I'm afraid I can't.","Me temo que no puedo."],["Sorry, I'm a bit busy.","Perdona, estoy algo ocupado."]], ex:["I'm afraid I'm busy right now.","Me temo que ahora estoy ocupado."]},
  {e:"☕", h:"Please & cheers", es:"Cortesía constante", i:[["Please","Por favor (úsalo siempre)"],["Cheers","Gracias (informal)"],["Ta","Gracias (muy coloquial)"]], ex:["A tea, please. Cheers!","Un té, por favor. ¡Gracias!"]}
 ], qs:[
  {q:"____ you mind helping me? (Would / Could)", a:"Would — 'Would you mind + -ing'."},
  {q:"Choose the best reply to 'Could you close the door?' – (a) 'Of course.' (b) 'Yes, I could.'", a:"(a) — 'Of course' acepta la petición; 'Yes, I could' suena raro."},
  {q:"Rewrite more politely: 'Give me a pen.'", a:"Could you give me a pen, please? / Would you mind passing me a pen?"}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"🎁", t:"Offering & Inviting", es:"Ofrecer e invitar", d:"Cómo ofrecer ayuda o comida e invitar a alguien a un plan.",
 boxes:[
  {e:"🍵", h:"Offering food & drink", es:"Ofrecer algo", i:[["Would you like a cup of tea?","¿Quieres una taza de té?"],["Can I get you a drink?","¿Te traigo algo de beber?"],["Help yourself to biscuits.","Sírvete galletas."]], ex:["Would you like a cuppa?","¿Te apetece un té?"]},
  {e:"🛠️", h:"Offering help", es:"Ofrecer ayuda", i:[["Can I give you a hand?","¿Te echo una mano?"],["Shall I carry that for you?","¿Te lo llevo?"],["Let me get that.","Deja, yo me encargo."]], ex:["Shall I open the door for you?","¿Te abro la puerta?"]},
  {e:"💌", h:"Inviting", es:"Invitar", i:[["Would you like to come to dinner?","¿Te gustaría venir a cenar?"],["Do you fancy going to the pub?","¿Te apetece ir al pub?"],["Why don't you join us?","¿Por qué no te unes?"]], ex:["Do you fancy a drink after work?","¿Te apetece tomar algo después del trabajo?"]},
  {e:"🍻", h:"Buying a round", es:"Pagar una ronda", i:[["It's my round.","Me toca pagar a mí."],["What are you having?","¿Qué vas a tomar?"],["This one's on me.","Esta la pago yo."]], ex:["Put your money away, it's on me.","Guarda el dinero, invito yo."]},
  {e:"👍", h:"Accepting", es:"Aceptar", i:[["Yes, please.","Sí, por favor."],["That would be lovely.","Eso sería estupendo."],["I'd love to.","Me encantaría."]], ex:["That would be lovely, thank you.","Sería estupendo, gracias."]},
  {e:"👎", h:"Declining", es:"Rechazar", i:[["No, thanks, I'm fine.","No, gracias, estoy bien."],["I'd love to, but I can't.","Me encantaría, pero no puedo."]], ex:["I'd love to, but I'm working late.","Me encantaría, pero trabajo hasta tarde."]}
 ], qs:[
  {q:"Complete: '____ I carry your bag?' (Shall / Do)", a:"Shall — 'Shall I...?' se usa para ofrecer ayuda."},
  {q:"Choose the best reply to 'Would you like a biscuit?' – (a) 'Yes, please.' (b) 'Yes, I like.'", a:"(a) — 'Yes, please' es la respuesta natural al ofrecimiento."},
  {q:"Rewrite as an invitation: 'Come to the pub with us.' (Do you fancy ...)", a:"Do you fancy coming to the pub with us? — 'fancy + -ing'."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"✅", t:"Accepting & Refusing", es:"Aceptar y rechazar con tacto", d:"Cómo decir sí o no sin sonar maleducado.",
 boxes:[
  {e:"😊", h:"Enthusiastic yes", es:"Aceptar con ganas", i:[["I'd love to!","¡Me encantaría!"],["That sounds great.","Suena genial."],["Brilliant, thanks!","¡Genial, gracias!"]], ex:["That sounds great. What time?","Suena genial. ¿A qué hora?"]},
  {e:"🙂", h:"Simple yes", es:"Aceptar sin más", i:[["Yes, please.","Sí, por favor."],["Go on, then.","Bueno, venga."],["Why not?","¿Por qué no?"]], ex:["Go on, then, just a small slice.","Venga, solo un trozo pequeño."]},
  {e:"🙅", h:"Polite no", es:"Rechazar amablemente", i:[["No, thank you.","No, gracias."],["I'm all right, thanks.","Estoy bien, gracias."],["Not for me, thanks.","Para mí no, gracias."]], ex:["I'm all right, thanks. I've just eaten.","Estoy bien, gracias. Acabo de comer."]},
  {e:"🧐", h:"Giving a reason", es:"Dar una excusa", i:[["I'm afraid I'm busy.","Me temo que estoy ocupado."],["I've already got plans.","Ya tengo planes."],["I'd better not.","Mejor que no."]], ex:["I'm afraid I've got plans that night.","Me temo que tengo planes esa noche."]},
  {e:"🤔", h:"Maybe / not sure", es:"Dudar", i:[["I'll have to check.","Tendré que verlo."],["Can I let you know?","¿Te lo puedo decir luego?"],["I'm not sure yet.","Aún no lo sé."]], ex:["Can I let you know tomorrow?","¿Te lo digo mañana?"]},
  {e:"⚠️", h:"Cultural note", es:"Nota cultural", i:[["'Maybe' can mean 'no'.","'Quizá' a veces significa 'no'."],["'I'll think about it' = probably no","'Lo pensaré' = probablemente no"],["Say thanks even when refusing","Da las gracias aunque rechaces"]], ex:["That's very kind, but I won't, thanks.","Muy amable, pero no, gracias."]}
 ], qs:[
  {q:"Polite refusal: 'No, I don't want.' → ?", a:"No, thank you. / I'm all right, thanks. — evita el 'I don't want' seco."},
  {q:"Choose the best reply to 'Fancy a drink tonight?' (you're busy) – (a) 'No.' (b) 'I'd love to, but I've got plans.'", a:"(b) — da las gracias y una razón; (a) suena brusco."},
  {q:"Rewrite more politely: 'I can't come.' (I'm afraid ...)", a:"I'm afraid I can't come. — 'I'm afraid' suaviza el rechazo."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"😔", t:"Apologising & Forgiving", es:"Pedir perdón y perdonar", d:"El 'sorry' británico: cuándo y cómo disculparse y responder.",
 boxes:[
  {e:"🙇", h:"Everyday sorry", es:"Disculpas cotidianas", i:[["Sorry!","¡Perdón!"],["Sorry about that.","Perdona por eso."],["Excuse me.","Disculpa / Con permiso."]], ex:["Sorry, I didn't see you there.","Perdón, no te vi."]},
  {e:"😟", h:"Stronger apologies", es:"Disculpas más fuertes", i:[["I'm so sorry.","Lo siento muchísimo."],["I'm terribly sorry.","Lo lamento mucho."],["I do apologise.","Le pido disculpas (formal)."]], ex:["I'm terribly sorry I'm late.","Lamento muchísimo llegar tarde."]},
  {e:"📝", h:"Explaining", es:"Explicar el motivo", i:[["It was my fault.","Fue culpa mía."],["I didn't mean to...","No quería..."],["The train was delayed.","El tren se retrasó."]], ex:["I didn't mean to upset you.","No quería molestarte."]},
  {e:"🙏", h:"Offering to fix it", es:"Reparar el daño", i:[["Let me make it up to you.","Déjame compensarte."],["It won't happen again.","No volverá a pasar."],["I'll pay for it.","Lo pagaré yo."]], ex:["I'll buy you a coffee to make up for it.","Te invito a un café para compensarlo."]},
  {e:"😌", h:"Forgiving", es:"Perdonar", i:[["Don't worry about it.","No te preocupes."],["It's fine / No harm done.","No pasa nada."],["Never mind.","No importa."]], ex:["Don't worry, no harm done.","No te preocupes, no pasó nada."]},
  {e:"⚠️", h:"Sorry vs pardon", es:"Sorry y pardon", i:[["Pardon? / Sorry?","¿Perdón? (no he oído)"],["Sorry I'm late","Perdona, llego tarde"],["Sorry for + -ing","Perdón por + verbo"]], ex:["Sorry for keeping you waiting.","Perdona por hacerte esperar."]}
 ], qs:[
  {q:"Sorry for ____ late. (be / being)", a:"being — 'sorry for + -ing'; también 'sorry I'm late'."},
  {q:"Choose the best reply to 'Sorry, I spilt your tea!' – (a) 'Don't worry, no harm done.' (b) 'It is your fault.'", a:"(a) — perdonar con naturalidad y sin dramatizar."},
  {q:"Rewrite more formally: 'Sorry I'm late.' (I ...)", a:"I do apologise for being late. — 'I do apologise' es formal."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"🙌", t:"Thanking & Responding", es:"Dar las gracias y responder", d:"Formas de agradecer, de informal a formal, y cómo contestar.",
 boxes:[
  {e:"🍺", h:"Informal thanks", es:"Gracias informal", i:[["Cheers!","¡Gracias!"],["Ta","Gracias (coloquial)"],["Thanks a lot.","Muchas gracias."]], ex:["Cheers, mate, that's great.","Gracias, colega, genial."]},
  {e:"🙏", h:"Standard thanks", es:"Gracias estándar", i:[["Thank you very much.","Muchas gracias."],["Thanks for your help.","Gracias por tu ayuda."],["That's very kind of you.","Qué amable de tu parte."]], ex:["Thanks for inviting me.","Gracias por invitarme."]},
  {e:"🎩", h:"Formal thanks", es:"Gracias formal", i:[["I'm most grateful.","Le estoy muy agradecido."],["I really appreciate it.","Lo agradezco mucho."],["Thank you for your assistance.","Gracias por su ayuda."]], ex:["I really appreciate your time.","Agradezco mucho su tiempo."]},
  {e:"😊", h:"Responding", es:"Responder a un gracias", i:[["You're welcome.","De nada."],["No problem.","Sin problema."],["Not at all.","En absoluto."]], ex:["Thanks! – No worries.","¡Gracias! – No te preocupes."]},
  {e:"🇬🇧", h:"British replies", es:"Respuestas típicas", i:[["Don't mention it.","No hay de qué."],["My pleasure.","Un placer."],["Any time.","Cuando quieras."]], ex:["Thanks a million! – Don't mention it.","¡Mil gracias! – No hay de qué."]},
  {e:"🚌", h:"Thanking everyone", es:"Hábito cultural", i:[["Thank the bus driver","Se da las gracias al conductor"],["Cheers, driver!","¡Gracias, conductor!"],["Thanks, have a good day!","¡Gracias, que tenga un buen día!"]], ex:["Thanks, driver! Have a good one!","¡Gracias, conductor! ¡Que le vaya bien!"]}
 ], qs:[
  {q:"'Thanks for the lift!' – '____' (No worries / Thanks)", a:"No worries — respuesta informal habitual a 'thanks'."},
  {q:"Choose the best formal thanks: (a) 'Ta!' (b) 'I'm most grateful for your assistance.'", a:"(b) — (a) es muy coloquial."},
  {q:"Rewrite more formally: 'Cheers for the help.'", a:"Thank you very much for your help. / I really appreciate your help."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"😤", t:"Making a Complaint", es:"Hacer una queja", d:"Cómo quejarte con firmeza pero con educación en situaciones reales.",
 boxes:[
  {e:"🗣️", h:"Starting politely", es:"Empezar con educación", i:[["Excuse me, I'm afraid there's a problem.","Disculpe, me temo que hay un problema."],["I'm sorry to make a fuss, but...","Perdone que me queje, pero..."]], ex:["I'm sorry to make a fuss, but this is cold.","Perdone que me queje, pero esto está frío."]},
  {e:"📉", h:"Stating the problem", es:"Exponer el problema", i:[["The soup isn't hot enough.","La sopa no está lo bastante caliente."],["It doesn't work properly.","No funciona bien."],["I've been waiting for an hour.","Llevo una hora esperando."]], ex:["I've been waiting over forty minutes.","Llevo más de cuarenta minutos esperando."]},
  {e:"🧾", h:"What you want", es:"Pedir una solución", i:[["Could I have a refund?","¿Podría pedir un reembolso?"],["Could you replace it, please?","¿Podría cambiármelo?"],["I'd like to speak to the manager.","Querría hablar con el encargado."]], ex:["I'd like a refund, please, if that's possible.","Querría un reembolso, por favor, si es posible."]},
  {e:"💪", h:"Firmer language", es:"Más firme", i:[["This is simply not acceptable.","Esto es inaceptable."],["I'm really not happy about this.","No estoy nada contento."],["I'd like to make a formal complaint.","Quiero presentar una queja formal."]], ex:["I'm afraid this is simply not good enough.","Me temo que esto no es aceptable."]},
  {e:"🎭", h:"British understatement", es:"Quejas a la británica", i:[["It's not quite what I expected.","No es lo que esperaba."],["It's a bit disappointing.","Es algo decepcionante."],["Not ideal, really.","No es lo ideal."]], ex:["It's not quite what I ordered.","No es exactamente lo que pedí."]},
  {e:"🤝", h:"Hearing the reply", es:"Responder a la solución", i:[["That's very kind of you.","Muy amable."],["That would be fine, thank you.","Eso estaría bien, gracias."],["I'll take it further.","Lo llevaré a instancias superiores."]], ex:["A replacement would be fine, thank you.","Un cambio estaría bien, gracias."]}
 ], qs:[
  {q:"Make it softer: 'This food is bad.' → 'I'm ____ this isn't quite right.' (afraid / sure)", a:"afraid — 'I'm afraid this isn't quite right.' suaviza la queja."},
  {q:"Choose the best complaint: (a) 'Your service is terrible!' (b) 'I'm sorry to make a fuss, but I've been waiting a long time.'", a:"(b) — más educado y más eficaz en el Reino Unido."},
  {q:"Rewrite more formally: 'I want my money back.' (Could I ...)", a:"Could I have a refund, please? — petición formal y cortés."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"🧭", t:"Asking for & Giving Directions", es:"Pedir y dar indicaciones", d:"Frases para orientarte y orientar a otros por una ciudad británica.",
 boxes:[
  {e:"❓", h:"Asking the way", es:"Preguntar", i:[["Excuse me, how do I get to the station?","Disculpe, ¿cómo llego a la estación?"],["Is there a chemist near here?","¿Hay una farmacia cerca?"],["Where's the nearest cash machine?","¿Dónde está el cajero más cercano?"]], ex:["Excuse me, where's the nearest Tube station?","Disculpe, ¿dónde está la estación de metro más cercana?"]},
  {e:"➡️", h:"Basic directions", es:"Indicaciones básicas", i:[["Turn left / right","Gira a la izquierda / derecha"],["Go straight on","Sigue derecho"],["Take the second turning on the left","Toma la segunda a la izquierda"]], ex:["Go straight on, then turn left.","Sigue derecho y luego gira a la izquierda."]},
  {e:"🏙️", h:"Landmarks", es:"Puntos de referencia", i:[["Go past the church.","Pasa por delante de la iglesia."],["It's opposite the post office.","Está enfrente de correos."],["It's next to the pub.","Está al lado del pub."]], ex:["It's on the corner, opposite the bank.","Está en la esquina, frente al banco."]},
  {e:"🚦", h:"Roads in Britain", es:"Vocabulario de calles", i:[["roundabout","rotonda"],["zebra crossing","paso de cebra"],["traffic lights","semáforos"],["pavement","acera"]], ex:["Take the second exit at the roundabout.","Toma la segunda salida en la rotonda."]},
  {e:"🚇", h:"Public transport", es:"Transporte", i:[["Take the Tube to Victoria.","Toma el metro hasta Victoria."],["Change at King's Cross.","Haz transbordo en King's Cross."],["Mind the gap!","¡Cuidado con el hueco!"]], ex:["Change at Oxford Circus for the Central line.","Cambia en Oxford Circus a la línea Central."]},
  {e:"⏱️", h:"Distance & checking", es:"Distancia y confirmar", i:[["It's about five minutes' walk.","Está a unos cinco minutos andando."],["You can't miss it.","No tiene pérdida."],["Sorry, I'm not from round here.","Lo siento, no soy de aquí."]], ex:["It's ten minutes on foot. You can't miss it.","Está a diez minutos andando. No tiene pérdida."]}
 ], qs:[
  {q:"British word: 'Walk on the ____' (sidewalk / pavement)", a:"pavement — 'sidewalk' es americano."},
  {q:"Choose the best reply to 'Sorry, I'm not from round here.' – (a) 'No problem, thanks anyway.' (b) 'Why not?'", a:"(a) — respuesta educada a quien no puede ayudar."},
  {q:"Rewrite more politely: 'Where is the station?' (Excuse me, could you tell me ...)", a:"Excuse me, could you tell me where the station is? — pregunta indirecta, orden normal."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"📞", t:"Talking on the Phone", es:"Hablar por teléfono", d:"Frases útiles para llamar, contestar y dejar mensajes.",
 boxes:[
  {e:"☎️", h:"Answering", es:"Contestar", i:[["Hello, Smith's Garage.","Taller Smith, dígame."],["Good morning, Jane speaking.","Buenos días, le habla Jane."],["Hello?","¿Hola? (al contestar)"]], ex:["Good morning, Hudson Bank, Ella speaking.","Buenos días, Banco Hudson, le atiende Ella."]},
  {e:"📲", h:"Making a call", es:"Llamar", i:[["Hello, it's Maria here.","Hola, soy María."],["Could I speak to Mr Jones, please?","¿Podría hablar con el Sr. Jones?"],["I'm calling about...","Llamo por..."]], ex:["I'm calling about your advert.","Llamo por su anuncio."]},
  {e:"⏳", h:"Waiting", es:"Esperar", i:[["Hold the line, please.","No cuelgue, por favor."],["I'll put you through.","Le paso."],["One moment, please.","Un momento, por favor."]], ex:["Please hold. I'll put you through.","Espere, le paso."]},
  {e:"📝", h:"Leaving a message", es:"Dejar un mensaje", i:[["Can I leave a message?","¿Puedo dejar un mensaje?"],["Could you ask him to call me back?","¿Podría decirle que me llame?"],["Can I take a message?","¿Quiere dejar un recado?"]], ex:["Could you ask her to ring me back?","¿Podría pedirle que me devuelva la llamada?"]},
  {e:"🔊", h:"Problems", es:"Problemas", i:[["Sorry, the line's bad.","Perdona, se oye mal."],["Could you speak up / repeat that?","¿Puedes hablar más alto / repetir?"],["I think we got cut off.","Creo que se cortó."]], ex:["Sorry, could you say that again?","Perdona, ¿puedes repetirlo?"]},
  {e:"👋", h:"Ending the call", es:"Terminar", i:[["Thanks for calling.","Gracias por llamar."],["Speak soon.","Hablamos pronto."],["Bye for now.","Hasta luego."]], ex:["Thanks for your help. Bye for now!","Gracias por tu ayuda. ¡Hasta luego!"]}
 ], qs:[
  {q:"Complete: 'Hold the ____, please.' (line / phone)", a:"line — 'Hold the line' = no cuelgue."},
  {q:"Choose the best reply to 'Can I take a message?' – (a) 'Yes, could you ask him to ring me back?' (b) 'No message is me.'", a:"(a) — petición clara y educada."},
  {q:"Rewrite more politely: 'Who is speaking?' (May I ...)", a:"May I ask who's calling? — fórmula educada para identificar al llamante."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"📅", t:"Booking & Making Appointments", es:"Reservar y pedir cita", d:"Cómo reservar mesa, hotel o cita médica en el Reino Unido.",
 boxes:[
  {e:"🍽️", h:"Booking a table", es:"Reservar mesa", i:[["I'd like to book a table for four.","Quiero reservar mesa para cuatro."],["Do you have a table for tonight?","¿Tienen mesa para esta noche?"],["Is there a table for 8 pm?","¿Hay mesa a las 8?"]], ex:["I'd like to book a table for two at eight.","Quiero reservar mesa para dos a las ocho."]},
  {e:"🏨", h:"Booking a room", es:"Reservar habitación", i:[["I'd like a double room for two nights.","Quiero una habitación doble dos noches."],["Is breakfast included?","¿Está incluido el desayuno?"],["Do you have any vacancies?","¿Tienen habitaciones libres?"]], ex:["Do you have any vacancies this weekend?","¿Tienen habitaciones libres este fin de semana?"]},
  {e:"🩺", h:"GP appointment", es:"Cita con el médico", i:[["I'd like to make an appointment.","Quiero pedir cita."],["Is the doctor available on Monday?","¿Está el doctor el lunes?"],["It's urgent.","Es urgente."]], ex:["I'd like to see a GP as soon as possible.","Quiero ver a un médico de cabecera lo antes posible."]},
  {e:"🕒", h:"Times & dates", es:"Horas y fechas", i:[["How about Tuesday at half past two?","¿Qué tal el martes a las dos y media?"],["Is 10 am convenient?","¿Le viene bien a las 10?"],["Are you free on the 5th?","¿Está libre el día 5?"]], ex:["Would Friday morning suit you?","¿Le iría bien el viernes por la mañana?"]},
  {e:"🔁", h:"Changing & cancelling", es:"Cambiar o cancelar", i:[["Could I reschedule?","¿Podría cambiar la cita?"],["I'm afraid I need to cancel.","Me temo que tengo que cancelar."],["Could we move it to Thursday?","¿Podemos pasarlo al jueves?"]], ex:["I'm afraid I need to cancel my booking.","Me temo que tengo que cancelar mi reserva."]},
  {e:"✅", h:"Confirming", es:"Confirmar", i:[["Could you confirm that, please?","¿Podría confirmarlo?"],["Under the name of Garcia","A nombre de García"],["Could you spell that?","¿Puede deletrearlo?"]], ex:["That's booked under the name Garcia.","Está reservado a nombre de García."]}
 ], qs:[
  {q:"Say politely: 'I want a table.' → 'I'd ____ to book a table.' (like / want)", a:"like — 'I'd like to...' es la forma educada."},
  {q:"Choose the best reply to 'Would Friday suit you?' – (a) 'Friday would be perfect, thank you.' (b) 'Friday I am.'", a:"(a) — acepta la hora con naturalidad."},
  {q:"Rewrite more politely: 'Change my booking to Monday.' (Could I ...)", a:"Could I change my booking to Monday, please? — petición cortés."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"☕", t:"Ordering at a Café or Pub", es:"Pedir en una cafetería o pub", d:"Cómo pedir bebidas y comida en un pub o café británico.",
 boxes:[
  {e:"🛎️", h:"Ordering", es:"Hacer el pedido", i:[["Could I have a latte, please?","¿Me pone un café con leche?"],["Can I get a pint of bitter?","¿Me pone una pinta de cerveza bitter (tipo ale)?"],["I'll have the fish and chips.","Tomaré el fish and chips."]], ex:["Could I have a flat white, please?","¿Me pone un flat white, por favor?"]},
  {e:"🍺", h:"At the pub", es:"En el pub", i:[["You order at the bar.","Se pide en la barra."],["A pint of lager, please.","Una pinta de cerveza lager, por favor."],["Is food served all day?","¿Sirven comida todo el día?"]], ex:["Two pints of lager and a packet of crisps, please.","Dos pintas de lager y una bolsa de papitas fritas, por favor."]},
  {e:"🫖", h:"Tea culture", es:"Cultura del té", i:[["a cuppa","una taza de té (coloquial)"],["milk and one sugar","con leche y un azúcar"],["a pot of tea for two","una tetera para dos"]], ex:["Tea with milk, no sugar, please.","Té con leche, sin azúcar, por favor."]},
  {e:"🍰", h:"Eating in or out", es:"Para tomar aquí o llevar", i:[["Eat in or take away?","¿Aquí o para llevar?"],["To take away, please.","Para llevar, por favor."],["Anything else?","¿Algo más?"]], ex:["Could I have a sausage roll to take away?","¿Me pone un rollo de salchicha para llevar?"]},
  {e:"💷", h:"Paying", es:"Pagar", i:[["Could I have the bill, please?","¿Me trae la cuenta?"],["Can I pay by card?","¿Puedo pagar con tarjeta?"],["Is service included?","¿Está incluido el servicio?"]], ex:["Could we have the bill, please?","¿Nos trae la cuenta, por favor?"]},
  {e:"💡", h:"Customs", es:"Costumbres", i:[["Tipping is about 10–12%","La propina es del 10–12 %"],["No tipping at the bar","No se da propina en la barra"],["Say 'cheers' when served","Di 'cheers' al recibir tu bebida"]], ex:["Cheers! How much is that?","¡Gracias! ¿Cuánto es?"]}
 ], qs:[
  {q:"At a pub you usually order ____. (at the bar / from a waiter)", a:"at the bar — normalmente se pide y se paga en la barra."},
  {q:"Choose the best reply to 'Eat in or take away?' – (a) 'Take away, please.' (b) 'I eat the food.'", a:"(a) — respuesta directa y educada."},
  {q:"Rewrite more politely: 'Give me a coffee.' (Could I ...)", a:"Could I have a coffee, please? — nunca pidas en imperativo."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"⚖️", t:"Agreeing & Disagreeing", es:"Estar de acuerdo y discrepar", d:"Cómo mostrar acuerdo o desacuerdo con distintos grados de fuerza.",
 boxes:[
  {e:"💯", h:"Strong agreement", es:"Acuerdo total", i:[["Absolutely.","Totalmente."],["Exactly!","¡Exacto!"],["I couldn't agree more.","No podría estar más de acuerdo."]], ex:["I couldn't agree more with you.","No podría estar más de acuerdo contigo."]},
  {e:"👍", h:"Mild agreement", es:"Acuerdo moderado", i:[["I suppose so.","Supongo que sí."],["That's true.","Es verdad."],["You've got a point.","Tienes razón en eso."]], ex:["You've got a point there.","En eso tienes razón."]},
  {e:"🤔", h:"Partial agreement", es:"Acuerdo parcial", i:[["Yes, but...","Sí, pero..."],["I see what you mean, but...","Entiendo lo que dices, pero..."],["That's true up to a point.","Es cierto hasta cierto punto."]], ex:["I see what you mean, but I'm not sure.","Entiendo lo que dices, pero no estoy seguro."]},
  {e:"🙅", h:"Polite disagreement", es:"Discrepar con educación", i:[["I'm not sure I agree.","No estoy seguro de estar de acuerdo."],["I'm afraid I see it differently.","Me temo que lo veo distinto."],["I don't really see it that way.","Yo no lo veo así."]], ex:["I'm afraid I don't really agree with that.","Me temo que no estoy muy de acuerdo con eso."]},
  {e:"🚫", h:"Strong disagreement", es:"Desacuerdo fuerte", i:[["I totally disagree.","No estoy nada de acuerdo."],["That's nonsense!","¡Eso es absurdo!"],["No way!","¡Ni hablar!"]], ex:["I totally disagree with that.","Estoy en total desacuerdo."]},
  {e:"🎭", h:"British style", es:"Estilo británico", i:[["'I hear what you say' = I disagree","'Te escucho' = no estoy de acuerdo"],["'With respect...' = I disagree","'Con el debido respeto...' = no estoy de acuerdo"],["'Interesting idea' = maybe not","'Idea interesante' = quizá no"]], ex:["That's an interesting idea, but...","Es una idea interesante, pero..."]}
 ], qs:[
  {q:"Agree: 'I couldn't ____ more.' (agree / disagree)", a:"agree — 'I couldn't agree more' = totalmente de acuerdo."},
  {q:"Choose the most polite disagreement: (a) 'You're wrong.' (b) 'I'm afraid I see it differently.'", a:"(b) — discrepar sin atacar es lo habitual en el Reino Unido."},
  {q:"Rewrite more politely: 'I don't agree with you.' (I'm not ...)", a:"I'm not sure I agree (with you). — suaviza el desacuerdo."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"💭", t:"Giving Opinions", es:"Dar opiniones", d:"Expresiones para opinar con matices y de forma educada.",
 boxes:[
  {e:"🗨️", h:"Stating your view", es:"Expresar tu punto de vista", i:[["In my opinion...","En mi opinión..."],["I think / I reckon...","Creo..."],["As far as I'm concerned...","Por lo que a mí respecta..."]], ex:["I reckon it's a good idea.","Creo que es buena idea."]},
  {e:"🧸", h:"Softening", es:"Suavizar", i:[["I tend to think...","Tiendo a pensar..."],["It seems to me that...","Me parece que..."],["If you ask me...","Si me preguntas..."]], ex:["It seems to me that prices are too high.","Me parece que los precios son demasiado altos."]},
  {e:"❓", h:"Asking for opinions", es:"Pedir opinión", i:[["What do you think?","¿Qué opinas?"],["How do you feel about it?","¿Qué te parece?"],["Do you agree?","¿Estás de acuerdo?"]], ex:["What do you make of the new manager?","¿Qué opinas del nuevo jefe?"]},
  {e:"🔥", h:"Strong opinions", es:"Opiniones firmes", i:[["I firmly believe...","Creo firmemente..."],["I'm convinced that...","Estoy convencido de que..."],["Without a doubt...","Sin duda..."]], ex:["I'm convinced it's the right decision.","Estoy convencido de que es la decisión correcta."]},
  {e:"⚖️", h:"Balancing", es:"Equilibrar", i:[["On the one hand... on the other","Por un lado... por otro"],["To be fair...","Para ser justos..."],["It depends.","Depende."]], ex:["To be fair, it's not that expensive.","Para ser justos, no es tan caro."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["I agree (not 'I'm agree')","Estoy de acuerdo (sin 'be')"],["I don't think it's fair","No creo que sea justo (se niega 'think')"],["In my opinion (not 'in my opinion, I think')","En mi opinión (no repitas)"]], ex:["I don't think he's right.","No creo que tenga razón."]}
 ], qs:[
  {q:"Correct: 'I think it isn't a good plan.' (more natural)", a:"I don't think it's a good plan. — se niega 'think'."},
  {q:"Choose the best reply to 'What do you think of the film?' – (a) 'To be honest, I found it a bit slow.' (b) 'I am thinking the film.'", a:"(a) — opinión suavizada y natural."},
  {q:"Rewrite more tactfully: 'This idea is bad.' (It seems to me ...)", a:"It seems to me that this idea isn't ideal. — suaviza la crítica."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"💡", t:"Giving Advice & Making Suggestions", es:"Aconsejar y sugerir", d:"Estructuras para dar consejos y proponer ideas.",
 boxes:[
  {e:"👉", h:"Should", es:"Deberías", i:[["You should see a doctor.","Deberías ver a un médico."],["You shouldn't worry.","No deberías preocuparte."],["You ought to rest.","Deberías descansar."]], ex:["You should get some sleep.","Deberías dormir un poco."]},
  {e:"🗣️", h:"If I were you", es:"Yo en tu lugar", i:[["If I were you, I'd...","Yo en tu lugar..."],["I'd advise you to...","Te aconsejaría..."],["Why don't you...?","¿Por qué no...?"]], ex:["If I were you, I'd take the train.","Yo en tu lugar iría en tren."]},
  {e:"🤝", h:"Suggestions", es:"Sugerencias", i:[["Let's go for a walk.","Vayamos a dar un paseo."],["How about going to the cinema?","¿Qué tal ir al cine?"],["Shall we get a takeaway?","¿Pedimos comida para llevar?"]], ex:["How about trying that new café?","¿Qué tal probar esa cafetería nueva?"]},
  {e:"🧸", h:"Gentle advice", es:"Consejo suave", i:[["Have you thought about...?","¿Has pensado en...?"],["Maybe you could...","Quizá podrías..."],["It might be worth...","Podría valer la pena..."]], ex:["It might be worth asking a friend.","Podría valer la pena preguntar a un amigo."]},
  {e:"✅", h:"Responding", es:"Responder", i:[["Good idea!","¡Buena idea!"],["That's a thought.","Es una posibilidad (en la que no había pensado)."],["I'll think about it.","Lo pensaré."]], ex:["Good idea, I'll try that.","Buena idea, lo probaré."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["How about + -ing","¿Qué tal + verbo en -ing?"],["Why don't we + verb","¿Por qué no + verbo base?"],["Shall we + verb?","¿Hacemos...? (verbo base)"]], ex:["Why don't we meet at six?","¿Por qué no quedamos a las seis?"]}
 ], qs:[
  {q:"'How about ____ to the park?' (go / going)", a:"going — 'How about + -ing'."},
  {q:"Choose the best reply to 'Why don't you take a day off?' – (a) 'Good idea, I might.' (b) 'Because I don't.'", a:"(a) — respuesta natural a un consejo."},
  {q:"Rewrite as softer advice: 'You must see a doctor.' (If I were you, ...)", a:"If I were you, I'd see a doctor. — consejo más suave que 'must'."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B1", icon:"🗓️", t:"Making Plans & Arrangements", es:"Hacer planes y quedar", d:"Frases para proponer, fijar y cambiar planes con amigos.",
 boxes:[
  {e:"❓", h:"Asking about plans", es:"Preguntar por planes", i:[["What are you up to this weekend?","¿Qué haces este fin de semana?"],["Are you doing anything on Saturday?","¿Haces algo el sábado?"],["Are you free tonight?","¿Estás libre esta noche?"]], ex:["What are you up to tonight?","¿Qué haces esta noche?"]},
  {e:"💡", h:"Proposing", es:"Proponer", i:[["Fancy a pint after work?","¿Te apetece una pinta tras el trabajo?"],["Shall we meet at six?","¿Quedamos a las seis?"],["Let's meet outside the Tube.","Quedemos fuera del metro."]], ex:["Shall we meet outside the cinema at seven?","¿Quedamos a las siete fuera del cine?"]},
  {e:"📍", h:"Fixing details", es:"Concretar", i:[["Where shall we meet?","¿Dónde quedamos?"],["What time suits you?","¿Qué hora te va bien?"],["I'll text you the address.","Te mando la dirección por mensaje."]], ex:["What time suits you best?","¿Qué hora te viene mejor?"]},
  {e:"🔮", h:"Future forms", es:"Formas de futuro", i:[["I'm meeting Ben at 8.","Quedo con Ben a las 8 (plan fijado)."],["I'm going to book a table.","Voy a reservar mesa (intención)."],["I'll call you later.","Te llamo luego (decisión en el momento)."]], ex:["I'm seeing the dentist on Friday.","Voy al dentista el viernes."]},
  {e:"🔁", h:"Changing plans", es:"Cambiar planes", i:[["I'm afraid I can't make it.","Me temo que no puedo ir."],["Can we rearrange?","¿Podemos reorganizar?"],["Something's come up.","Me ha surgido algo."]], ex:["Sorry, something's come up. Can we rearrange?","Perdona, me ha surgido algo. ¿Podemos cambiarlo?"]},
  {e:"👍", h:"Confirming", es:"Confirmar", i:[["Sounds good.","Me parece bien."],["See you there!","¡Nos vemos allí!"],["I'll be there.","Allí estaré."]], ex:["Sounds good. See you at seven!","Perfecto. ¡Nos vemos a las siete!"]}
 ], qs:[
  {q:"Arrangement: 'I ____ my cousin on Sunday.' (meet / am meeting)", a:"am meeting — presente continuo para planes fijados."},
  {q:"Choose the best reply to 'Shall we say seven?' – (a) 'Sounds good.' (b) 'Yes, we shall say.'", a:"(a) — respuesta natural para confirmar."},
  {q:"Rewrite politely: 'I can't come, I have something.' (I'm afraid ...)", a:"I'm afraid I can't make it; something's come up. — excusa educada."}
 ]},
{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"B2", icon:"🧑", t:"Describing People & Places", es:"Describir personas y lugares", d:"Vocabulario y estructuras para describir con detalle.",
 boxes:[
  {e:"🧍", h:"Appearance", es:"Aspecto físico", i:[["She's tall, with curly fair hair.","Es alta, con pelo rizado rubio."],["He's in his thirties.","Tiene unos treinta años."],["He's quite well-built.","Es bastante fornido."]], ex:["She's slim, with long dark hair.","Es delgada, con pelo largo y oscuro."]},
  {e:"😄", h:"Personality", es:"Personalidad", i:[["easy-going","tranquilo, de trato fácil"],["bubbly","alegre, vivaz"],["reserved","reservado"],["bossy","mandón"]], ex:["He's easy-going and very funny.","Es tranquilo y muy gracioso."]},
  {e:"👕", h:"Clothes & style", es:"Ropa y estilo", i:[["She's smartly dressed.","Va muy elegante."],["He's wearing a cosy jumper.","Lleva un suéter calentito."],["scruffy","desaliñado"]], ex:["He's wearing a smart suit and tie.","Lleva un traje elegante y corbata."]},
  {e:"🏘️", h:"Places: town", es:"Lugares: ciudad", i:[["It's a lively, buzzing city.","Es una ciudad animada."],["a quiet little village","un pueblecito tranquilo"],["It's quite run-down.","Está bastante deteriorado."]], ex:["It's a charming village with a pretty green.","Es un pueblo encantador con un bonito prado comunal."]},
  {e:"🏠", h:"Places: homes", es:"Lugares: casas", i:[["a semi-detached house","casa pareada (unida por un lado)"],["a flat on the third floor","un departamento en el tercer piso"],["It's spacious and bright.","Es amplio y luminoso."]], ex:["We live in a small terraced house.","Vivimos en una casa pequeña en hilera (unida a otras a ambos lados)."]},
  {e:"✨", h:"Useful adjectives", es:"Adjetivos útiles", i:[["lovely / gorgeous","precioso"],["dull / dreary","aburrido, gris"],["breathtaking","impresionante"]], ex:["The view was absolutely breathtaking.","La vista era impresionante."]}
 ], qs:[
  {q:"Put the words in order: wooden / lovely / table / old", a:"a lovely old wooden table — opinión + edad + material + sustantivo."},
  {q:"Choose the best description of someone who is calm and relaxed: (a) bossy (b) easy-going", a:"(b) easy-going — tranquilo; 'bossy' es mandón."},
  {q:"Rewrite using 'with': 'She has long dark hair and she is tall.'", a:"She's tall, with long dark hair. — 'with' para rasgos físicos."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"📖", t:"Telling a Story", es:"Contar una historia", d:"Expresiones narrativas para organizar y animar tu relato.",
 boxes:[
  {e:"🎬", h:"Starting", es:"Empezar", i:[["Guess what happened!","¡Adivina qué pasó!"],["It all started when...","Todo empezó cuando..."],["You'll never believe this...","No te vas a creer esto..."]], ex:["You'll never believe what happened on the bus.","No te vas a creer lo que pasó en el autobús."]},
  {e:"⏱️", h:"Sequencing", es:"Ordenar", i:[["First / then / after that","Primero / luego / después"],["Meanwhile...","Mientras tanto..."],["By the time we arrived...","Para cuando llegamos..."]], ex:["By the time I got there, it was shut.","Para cuando llegué, estaba cerrado."]},
  {e:"💥", h:"Sudden events", es:"Sucesos repentinos", i:[["Suddenly...","De repente..."],["All of a sudden...","De golpe..."],["Out of the blue...","De la nada..."]], ex:["All of a sudden, the lights went out.","De golpe se apagaron las luces."]},
  {e:"🕰️", h:"Past tenses", es:"Tiempos pasados", i:[["I was walking (background)","Caminaba (acción de fondo)"],["I met him (main event)","Lo encontré (acción principal)"],["I had already left (before)","Ya me había ido (antes)"]], ex:["I was walking home when it started to rain.","Iba caminando a casa cuando empezó a llover."]},
  {e:"😅", h:"Reactions", es:"Reaccionar", i:[["Fancy that!","¡Fíjate!"],["No way!","¡No me digas!"],["Seriously?","¿En serio?"]], ex:["No way! What did you do?","¡No me digas! ¿Qué hiciste?"]},
  {e:"🏁", h:"Ending", es:"Terminar", i:[["In the end...","Al final..."],["Long story short...","Resumiendo..."],["Luckily / Fortunately...","Por suerte..."]], ex:["Long story short, we missed the train.","Resumiendo, perdimos el tren."]}
 ], qs:[
  {q:"'I ____ (walk) home when it began to rain.'", a:"was walking — pasado continuo para la acción de fondo."},
  {q:"Choose the best reaction to 'I met the King yesterday!' – (a) 'No way! Seriously?' (b) 'I am meeting.'", a:"(a) — reacción natural al oír una historia."},
  {q:"Rewrite to shorten the story: 'To make a long story short, we left.' (Long ...)", a:"Long story short, we left. — resumen coloquial."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"🎩", t:"Formal vs Informal English", es:"Inglés formal e informal", d:"Cómo adaptar el registro según la situación.",
 boxes:[
  {e:"👋", h:"Greetings", es:"Saludos", i:[["Hi / Hiya","Hola (informal)"],["Good morning","Buenos días (formal)"],["How do you do?","Mucho gusto (muy formal)"]], ex:["Good morning, Mr Hall.","Buenos días, Sr. Hall."]},
  {e:"🙏", h:"Requests", es:"Peticiones", i:[["Can you help me?","¿Puedes ayudarme? (informal)"],["Could you possibly help me?","¿Podría ayudarme? (formal)"],["I would be grateful if you could...","Le agradecería que..."]], ex:["I would be grateful if you could reply soon.","Le agradecería que respondiera pronto."]},
  {e:"📚", h:"Vocabulary pairs", es:"Pares de vocabulario", i:[["get / obtain","conseguir / obtener"],["ask for / request","pedir / solicitar"],["buy / purchase","comprar / adquirir"],["help / assist","ayudar / prestar asistencia"]], ex:["I'd like to purchase a ticket.","Quisiera adquirir una entrada."]},
  {e:"✂️", h:"Contractions", es:"Contracciones", i:[["I'm, don't, can't","Contracciones (informal)"],["I am, do not, cannot","Formas completas (formal)"]], ex:["I cannot attend the meeting.","No puedo asistir a la reunión."]},
  {e:"🗯️", h:"Slang & phrasal verbs", es:"Argot y verbos frasales", i:[["quid","libra esterlina (argot)"],["knackered","agotado (muy coloquial)"],["find out / ascertain","averiguar (informal / formal)"]], ex:["I'm knackered, I mean, rather tired.","Estoy hecho polvo, es decir, bastante cansado."]},
  {e:"👋", h:"Endings", es:"Despedidas", i:[["Cheers / See you","Hasta luego (informal)"],["Yours sincerely","Atentamente (formal)"],["Kind regards","Saludos cordiales"]], ex:["Kind regards, Jo Smith","Saludos cordiales, Jo Smith"]}
 ], qs:[
  {q:"Make formal: 'Can you tell me the price?'", a:"Could you possibly tell me the price? — mayor distancia = más formal."},
  {q:"Choose the formal word: (a) buy (b) purchase", a:"(b) purchase — 'buy' es neutro/informal."},
  {q:"Choose the best reply in an interview to 'How are you?' – (a) 'Knackered, mate.' (b) 'Very well, thank you.'", a:"(b) — en situaciones formales evita el argot."}
 ]},
{ cat:"Communication & British Culture", type:"Structures", lvl:"B2", icon:"✉️", t:"Writing a Formal Email or Letter", es:"Escribir un email o carta formal", d:"Estructura y frases típicas de la correspondencia formal británica.",
 boxes:[
  {e:"🎯", h:"Opening", es:"Saludo", i:[["Dear Mr / Ms Brown,","Estimado/a Sr./Sra. Brown:"],["Dear Sir or Madam,","Estimados señores:"],["Dear Dr Evans,","Estimado Dr. Evans:"]], ex:["Dear Ms Taylor,","Estimada Sra. Taylor:"]},
  {e:"📝", h:"Purpose", es:"Motivo", i:[["I am writing to enquire about...","Le escribo para preguntar por..."],["I am writing with regard to...","Le escribo en relación con..."],["I am writing to complain about...","Le escribo para quejarme de..."]], ex:["I am writing to enquire about your course.","Le escribo para informarme sobre su curso."]},
  {e:"📎", h:"Requests & info", es:"Peticiones", i:[["I would be grateful if you could...","Le agradecería que..."],["Please find attached...","Adjunto encontrará..."],["Could you let me know...?","¿Podría decirme...?"]], ex:["Please find attached my CV.","Adjunto mi currículum."]},
  {e:"🙏", h:"Closing lines", es:"Cierre", i:[["I look forward to hearing from you.","Espero su respuesta."],["Thank you for your time.","Gracias por su tiempo."],["Please do not hesitate to contact me.","No dude en contactarme."]], ex:["I look forward to your reply.","Quedo a la espera de su respuesta."]},
  {e:"✍️", h:"Signing off", es:"Despedida", i:[["Yours faithfully (Dear Sir)","Atentamente (sin nombre)"],["Yours sincerely (Dear Mr X)","Atentamente (con nombre)"],["Kind regards (email)","Saludos cordiales (email)"]], ex:["Yours sincerely, Ana Ruiz","Atentamente, Ana Ruiz"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["No contractions in formal writing","Sin contracciones en textos formales"],["Use 'Ms' if unsure","Usa 'Ms' si dudas del estado civil"],["Date: 12 March 2025","Fecha: 12 de marzo de 2025 (sin coma ni 'de')"]], ex:["I do not wish to proceed.","No deseo continuar."]}
 ], qs:[
  {q:"Close: 'Dear Mr Hill,' → Yours ____. (faithfully / sincerely)", a:"sincerely — con nombre: sincerely; sin nombre: faithfully."},
  {q:"Choose the best opening line: (a) 'Hi, I want info.' (b) 'I am writing to enquire about your course.'", a:"(b) — registro formal y claro."},
  {q:"Rewrite formally: 'Tell me the price.' (Could you ...)", a:"Could you let me know the price? / I would be grateful if you could confirm the price."}
 ]},
{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"B1", icon:"📱", t:"Informal Messages & Texting Abbreviations", es:"Mensajes informales y abreviaturas", d:"Abreviaturas y estilo de los mensajes entre amigos.",
 boxes:[
  {e:"💬", h:"Common abbreviations", es:"Abreviaturas comunes", i:[["BTW = by the way","por cierto"],["LOL = laughing out loud","jajaja"],["IDK = I don't know","ni idea"],["BRB = be right back","vuelvo enseguida"]], ex:["BTW, are you free tonight?","Por cierto, ¿estás libre esta noche?"]},
  {e:"🔢", h:"Numbers & letters", es:"Números y letras", i:[["2 = to / too","a / también"],["u = you","tú / usted"],["gr8 = great","genial"],["l8r = later","luego"]], ex:["See u l8r!","¡Hasta luego!"]},
  {e:"👍", h:"Replies", es:"Respuestas", i:[["ta / thx = thanks","gracias"],["np = no problem","sin problema"],["ok / k","de acuerdo"]], ex:["Thx! – np!","¡Gracias! – ¡Sin problema!"]},
  {e:"📍", h:"Meeting up", es:"Quedar", i:[["OMW = on my way","voy de camino"],["ETA = estimated time of arrival","hora estimada de llegada"],["running late","voy con retraso"]], ex:["OMW, running 5 mins late.","Voy de camino, con 5 minutos de retraso."]},
  {e:"😂", h:"Emojis & kisses", es:"Emojis y besos", i:[["x = kiss (friendly)","beso (entre amigos)"],["xx = two kisses (very friendly)","dos besos (muy cariñoso)"],["xxx = lots of kisses (close friends or family)","muchos besos (amigos cercanos o familia)"]], ex:["Thanks so much! x","¡Muchas gracias! x"]},
  {e:"⚠️", h:"When not to use", es:"Cuándo evitarlas", i:[["Not in formal emails","No en emails formales"],["Not with your boss","No con tu jefe"],["Don't overuse them","No abuses de ellas"]], ex:["Dear Sir, thank you for your reply.","Estimado señor, gracias por su respuesta."]}
 ], qs:[
  {q:"What does 'OMW' mean?", a:"On my way — voy de camino."},
  {q:"Choose the best text reply to 'Meet at 7?' – (a) 'Sounds good, see u l8r!' (b) 'I hereby confirm my attendance.'", a:"(a) — entre amigos, informal y breve."},
  {q:"Rewrite formally: 'Thx, BTW can u send it 2day?'", a:"Thank you. By the way, could you send it today? — sin abreviaturas."}
 ]},
{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"B1", icon:"🔄", t:"British vs American Vocabulary", es:"Vocabulario británico vs americano", d:"Palabras distintas en Reino Unido y EE. UU. para el mismo objeto.",
 boxes:[
  {e:"🏠", h:"Home", es:"Hogar", i:[["flat (UK) / apartment (US)","departamento"],["lift (UK) / elevator (US)","ascensor"],["ground floor (UK) / first floor (US)","planta baja"]], ex:["I live in a flat on the ground floor.","Vivo en un departamento en la planta baja."]},
  {e:"🚗", h:"Transport", es:"Transporte", i:[["lorry / truck","camión"],["petrol / gas","gasolina"],["boot / trunk","baúl del auto (maletero)"],["motorway / freeway","autopista"]], ex:["Put the bags in the boot.","Pon las bolsas en el maletero."]},
  {e:"🍬", h:"Food", es:"Comida", i:[["chips / fries","papas fritas gruesas (UK / US)"],["crisps / chips","papitas de bolsa (UK / US)"],["biscuit / cookie","galleta"],["sweets / candy","caramelos"]], ex:["Fish and chips, and a packet of crisps.","Fish and chips y una bolsa de papitas."]},
  {e:"👕", h:"Clothes", es:"Ropa", i:[["trainers / sneakers","zapatillas deportivas"],["jumper / sweater","suéter"],["trousers / pants","pantalones"],["vest / undershirt","camiseta interior"]], ex:["I wore my trainers and jumper.","Llevé mis zapatillas y mi suéter."]},
  {e:"🛍️", h:"Shopping & money", es:"Compras", i:[["queue / line","fila"],["shop / store","tienda"],["bin / trash can","papelera"],["note / bill","billete"]], ex:["There's a long queue at the shop.","Hay una fila larga en la tienda."]},
  {e:"📬", h:"Everyday", es:"Cotidiano", i:[["post / mail","correo"],["holiday / vacation","vacaciones"],["rubbish / garbage","basura"],["torch / flashlight","linterna"]], ex:["We're on holiday next week.","Estamos de vacaciones la semana que viene."]}
 ], qs:[
  {q:"British for 'elevator'?", a:"lift — 'elevator' es americano."},
  {q:"Choose the British word: (a) fries (b) chips (thin, fried potato strips in a UK takeaway)", a:"(b) chips — en EE. UU. son 'fries'; ojo: 'crisps' son las de bolsa."},
  {q:"Rewrite in British English: 'I live in an apartment near the subway.'", a:"I live in a flat near the Tube/underground. — flat, Tube."}
 ]},
{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"B1", icon:"🔤", t:"British vs American Spelling", es:"Ortografía británica vs americana", d:"Patrones habituales que diferencian la ortografía de ambas variedades.",
 boxes:[
  {e:"🎨", h:"-our / -or", es:"-our / -or", i:[["colour / color","color"],["favourite / favorite","favorito"],["neighbour / neighbor","vecino"]], ex:["My favourite colour is blue.","Mi color favorito es el azul."]},
  {e:"🏢", h:"-re / -er", es:"-re / -er", i:[["centre / center","centro"],["theatre / theater","teatro"],["metre / meter","metro"]], ex:["The theatre is in the city centre.","El teatro está en el centro de la ciudad."]},
  {e:"🧠", h:"-ise / -ize", es:"-ise / -ize", i:[["organise / organize","organizar"],["realise / realize","darse cuenta"],["recognise / recognize","reconocer"]], ex:["We need to organise the party.","Tenemos que organizar la fiesta."]},
  {e:"✌️", h:"Double L", es:"Doble L", i:[["travelling / traveling","viajando"],["cancelled / canceled","cancelado"],["jewellery / jewelry","joyas"]], ex:["The train was cancelled.","El tren fue cancelado."]},
  {e:"🛡️", h:"-ce / -se", es:"-ce / -se", i:[["licence (n) / license","licencia (sustantivo)"],["defence / defense","defensa"],["practise (v) / practice","practicar (verbo)"]], ex:["I practise English every day.","Practico inglés cada día."]},
  {e:"🔀", h:"Other differences", es:"Otras diferencias", i:[["grey / gray","gris"],["programme / program","programa (en informática, 'program' también en UK)"],["cheque / check","cheque"],["tyre / tire","neumático"]], ex:["The sky is grey today.","El cielo está gris hoy."]}
 ], qs:[
  {q:"British spelling: 'I like this (color / colour).'", a:"colour — el inglés británico usa -our."},
  {q:"Choose the British spelling: (a) theater (b) theatre", a:"(b) theatre — británico: -re."},
  {q:"Rewrite in British spelling: 'My neighbor organized a trip to the center.'", a:"My neighbour organised a trip to the centre. — -our, -ise, -re."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"🎭", t:"British Humour, Understatement & Sarcasm", es:"Humor británico, ironía y sarcasmo", d:"Cómo interpretar lo que los británicos dicen (y lo que quieren decir).",
 boxes:[
  {e:"🙊", h:"Understatement", es:"Quitar importancia", i:[["Not bad.","Bastante bien (elogio moderado)"],["A bit of a problem","Un problema serio"],["Not ideal","Fatal (muy malo)"]], ex:["It's a bit damp. (It's pouring.)","Está algo húmedo. (En realidad diluvia.)"]},
  {e:"🔄", h:"What they mean", es:"Lo que quieren decir", i:[["'With respect...'","No estoy de acuerdo"],["'Quite good'","Bastante bueno (a veces, solo aceptable)"],["'I'll bear it in mind'","Probablemente no lo haré"]], ex:["That's an interesting idea. (= I don't like it.)","Es una idea interesante. (= No me gusta.)"]},
  {e:"😏", h:"Sarcasm", es:"Sarcasmo", i:[["Oh, brilliant.","Ah, genial (irónico)"],["Great, just what I needed.","Estupendo, justo lo que necesitaba"],["Thanks a lot.","Muchas gracias (irónico)"]], ex:["Oh, lovely. It's raining again.","Ah, qué bien. Llueve otra vez."]},
  {e:"🤣", h:"Self-deprecation", es:"Autocrítica con humor", i:[["I'm hopeless at cooking.","Soy un desastre cocinando."],["I'm not exactly an expert.","No soy precisamente un experto."]], ex:["I'm not exactly Gordon Ramsay.","No soy precisamente Gordon Ramsay."]},
  {e:"🎤", h:"Banter", es:"Bromas entre amigos", i:[["Cheeky!","¡Descarado!"],["Mate, you're having a laugh.","Colega, me estás tomando el pelo."],["to take the mickey","burlarse de alguien"]], ex:["Are you taking the mickey?","¿Te estás burlando de mí?"]},
  {e:"👀", h:"Tone clues", es:"Pistas de tono", i:[["Flat voice = irony","Voz plana = ironía"],["Deadpan face","Cara seria e inexpresiva"],["Check the context","Fíjate en el contexto"]], ex:["Well, that went well. (it didn't)","Bueno, eso salió bien. (en realidad, no)"]}
 ], qs:[
  {q:"'That's not bad' usually means…? (terrible / quite good)", a:"quite good — típico understatement británico."},
  {q:"Choose the best reply to a friend's joke 'You're a genius!' (sarcastic) – (a) 'Cheers, mate.' (b) 'Yes, I am a genius.'", a:"(a) — respuesta humilde y con humor."},
  {q:"Rewrite as British understatement: 'This is a disaster!'", a:"This isn't ideal. / It's a bit of a problem. — quitar importancia."}
 ]},
{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"B2", icon:"⚠️", t:"False Friends (Spanish–English)", es:"Falsos amigos español–inglés", d:"Palabras parecidas al español pero con significado distinto.",
 boxes:[
  {e:"📚", h:"Education", es:"Educación", i:[["library","biblioteca (no 'librería'; librería = bookshop)"],["college","centro de estudios (no 'colegio')"],["lecture","conferencia o clase magistral (no 'lectura')"]], ex:["I'm going to the library.","Voy a la biblioteca."]},
  {e:"😊", h:"Feelings", es:"Sentimientos", i:[["embarrassed","avergonzado (no 'embarazada')"],["sensible","sensato (no 'sensible')"],["sensitive","sensible"]], ex:["I'm embarrassed, not pregnant!","¡Estoy avergonzada, no embarazada!"]},
  {e:"🛒", h:"Time & help", es:"Tiempo y ayuda", i:[["actually","en realidad (no 'actualmente')"],["currently","actualmente"],["assist","ayudar (no 'asistir a')"]], ex:["Actually, I'm busy.","En realidad, estoy ocupado."]},
  {e:"🥗", h:"Health & food", es:"Salud y comida", i:[["preservative","conservante (no 'preservativo')"],["constipated","estreñido (no 'constipado')"],["I have a cold","Estoy resfriado"]], ex:["I have a cold, I'm not constipated.","Estoy resfriado, no estreñido."]},
  {e:"🏢", h:"Work & objects", es:"Trabajo y objetos", i:[["fabric","tela (no 'fábrica')"],["factory","fábrica"],["carpet","alfombra (no 'carpeta')"]], ex:["The factory makes fabric.","La fábrica produce tela."]},
  {e:"🎬", h:"Everyday", es:"Cotidiano", i:[["realise","darse cuenta (no 'realizar')"],["exit","salida (no 'éxito')"],["success","éxito"]], ex:["Follow the signs to the exit.","Sigue las señales hasta la salida."]}
 ], qs:[
  {q:"'Actualmente' in English = ?", a:"currently / at the moment — 'actually' = en realidad."},
  {q:"Choose the right word: 'I'm ____ about my English.' (embarrassed / pregnant)", a:"embarrassed — avergonzado; 'embarazada' = pregnant."},
  {q:"Rewrite correcting the false friend: 'I bought a book in the library.'", a:"I bought a book in the bookshop. — librería = bookshop."}
 ]},
{ cat:"Communication & British Culture", type:"Grammar", lvl:"B1", icon:"🚧", t:"Common Mistakes of Spanish Speakers", es:"Errores comunes de hispanohablantes", d:"Errores frecuentes de gramática y vocabulario y cómo evitarlos.",
 boxes:[
  {e:"🔢", h:"Common mistakes: age & states", es:"Edad y estados", i:[["I am 20 (not 'I have 20')","Tengo 20 años"],["I am hungry","Tengo hambre"],["I am cold","Tengo frío"]], ex:["I'm hungry and I'm 20.","Tengo hambre y tengo 20 años."]},
  {e:"🧱", h:"Subject & there is", es:"Sujeto y 'there is'", i:[["It is raining (needs 'it')","Llueve (hace falta sujeto)"],["There is a problem","Hay un problema"],["He likes dogs (needs 'he')","Le gustan los perros"]], ex:["It's cold. There are people outside.","Hace frío. Hay gente fuera."]},
  {e:"🗓️", h:"Present perfect vs past", es:"Presente perfecto", i:[["I have lived here for 5 years","Vivo aquí desde hace 5 años"],["I lived there in 2010","Viví allí en 2010"],["since / for","desde (fecha) / desde hace (periodo)"]], ex:["I've worked here since 2020.","Trabajo aquí desde 2020."]},
  {e:"🙋", h:"Prepositions", es:"Preposiciones", i:[["depend on","depender de"],["good at","bueno en"],["married to","casado con"]], ex:["She's good at languages.","Se le dan bien los idiomas."]},
  {e:"📚", h:"Uncountable nouns", es:"Nombres incontables", i:[["information (no 's')","información (sin plural)"],["advice (no 's')","consejos (sin plural)"],["The news is...","Las noticias son... (verbo en singular)"]], ex:["That's useful advice.","Son consejos útiles."]},
  {e:"🗣️", h:"Word order & questions", es:"Orden y preguntas", i:[["Where do you live?","¿Dónde vives? (necesita 'do')"],["I don't know where she is","No sé dónde está (orden afirmativo)"],["an expensive car","un auto caro (el adjetivo va antes del sustantivo)"]], ex:["Do you know where he lives?","¿Sabes dónde vive?"]}
 ], qs:[
  {q:"Correct: 'She have 30 years.'", a:"She is 30 (years old). — 'be' para la edad."},
  {q:"Choose the correct sentence: (a) 'I live here since 2020.' (b) 'I've lived here since 2020.'", a:"(b) — presente perfecto con 'since'."},
  {q:"Rewrite correctly: 'Is raining and have much informations.'", a:"It's raining and I have a lot of information. — sujeto 'it', 'a lot of' e 'information' incontable (sin 's')."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"🔀", t:"Linking Words: Contrast, Cause & Result", es:"Conectores: contraste, causa y consecuencia", d:"however, although, therefore, as a result y más para conectar ideas con claridad.",
 boxes:[
  {e:"⚔️", h:"Contrast (sentence start)", es:"Contraste", i:[["However, ...","Sin embargo, ..."],["Nevertheless, ...","No obstante, ..."],["On the other hand, ...","Por otro lado, ..."]], ex:["The hotel is cheap. However, it is noisy.","El hotel es barato. Sin embargo, es ruidoso."]},
  {e:"🔁", h:"Contrast (within a sentence)", es:"Contraste en la frase", i:[["although / even though + clause","aunque + oración"],["despite / in spite of + noun or -ing","a pesar de + sustantivo o -ing"],["whereas / while","mientras que"]], ex:["Although it rained, we enjoyed the match.","Aunque llovió, disfrutamos del partido."]},
  {e:"❓", h:"Cause", es:"Causa", i:[["because / since / as + clause","porque / ya que + oración"],["because of / due to + noun","a causa de / debido a + sustantivo"],["owing to","debido a (formal)"]], ex:["The train was cancelled because of the strike.","Cancelaron el tren a causa de la huelga."]},
  {e:"➡️", h:"Result", es:"Consecuencia", i:[["so + clause","así que"],["therefore / consequently","por lo tanto / en consecuencia"],["as a result","como resultado"]], ex:["It was raining, so we stayed in.","Llovía, así que nos quedamos dentro."]},
  {e:"✍️", h:"Punctuation & position", es:"Puntuación", i:[["However, (comma after)","'However' va seguido de coma"],["Semicolon + however + comma","punto y coma + however + coma"],["Although never takes 'but'","con 'although' no se usa 'but'"]], ex:["It was cheap; however, it was poor quality.","Era barato; sin embargo, era de mala calidad."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["Despite of ✘ → despite / in spite of","'despite' no lleva 'of'"],["Although... but ✘","No uses 'although' y 'but' juntos"],["Because of + clause ✘","'because of' va con sustantivo"]], ex:["Despite the rain, we went out.","A pesar de la lluvia, salimos."]}
 ], qs:[
  {q:"Fill the gap: '____ it was cold, we went swimming.' (Although / Despite)", a:"Although — va con oración; 'despite' + sustantivo."},
  {q:"Choose the best word: 'The flight was delayed ____ fog.' (because / because of)", a:"because of — antes de un sustantivo (fog)."},
  {q:"Rewrite with 'however': 'The food was lovely but the service was slow.'", a:"The food was lovely. However, the service was slow. — 'However,' con coma."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"➕", t:"Linking Words: Addition, Sequence & Purpose", es:"Conectores: adición, secuencia y finalidad", d:"moreover, in addition, afterwards, in order to y otros conectores útiles.",
 boxes:[
  {e:"➕", h:"Addition", es:"Añadir ideas", i:[["and / also / as well","y / también"],["in addition / moreover / furthermore","además (más formal)"],["besides","además (informal)"]], ex:["Moreover, the flat is close to the Tube.","Además, el departamento está cerca del metro."]},
  {e:"1️⃣", h:"Sequence: start", es:"Empezar la secuencia", i:[["First of all / To begin with","En primer lugar"],["Firstly, secondly, thirdly","Primero, segundo, tercero"]], ex:["First of all, let's check the map.","En primer lugar, miremos el mapa."]},
  {e:"⏭️", h:"Sequence: middle", es:"Continuar", i:[["then / next / after that","luego / después / a continuación"],["afterwards","después"],["meanwhile","mientras tanto"]], ex:["We had lunch and afterwards we went for a walk.","Comimos y después dimos un paseo."]},
  {e:"🏁", h:"Sequence: end", es:"Terminar", i:[["finally / lastly","por último / finalmente"],["in the end","al final"],["to sum up / in conclusion","en resumen / en conclusión"]], ex:["Finally, don't forget to say thank you.","Por último, no olvides dar las gracias."]},
  {e:"🎯", h:"Purpose", es:"Finalidad", i:[["to + verb","para + infinitivo"],["in order to + verb","con el fin de + infinitivo"],["so that + clause","para que + oración"]], ex:["I saved money in order to visit London.","Ahorré dinero con el fin de visitar Londres."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["Moreover, + comma","'Moreover' va con coma"],["in order to (not 'for + verb')","para + infinitivo, no 'for + verbo'"],["I went there to buy bread (not 'for buy')","Fui allí a comprar pan"]], ex:["I use this app to learn English.","Uso esta aplicación para aprender inglés."]}
 ], qs:[
  {q:"Fill the gap: 'I went to the shop ____ buy milk.' (to / for)", a:"to — 'to + verbo' expresa finalidad."},
  {q:"Choose the most formal: (a) besides (b) furthermore", a:"(b) furthermore — más formal; 'besides' es informal."},
  {q:"Rewrite with 'so that': 'I left early to catch the train.' (so that I ...)", a:"I left early so that I could catch the train. — 'so that' + oración."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"🗯️", t:"Discourse Markers in Speech", es:"Marcadores del discurso oral", d:"anyway, actually, to be honest, as a matter of fact, by the way: el hilo de la conversación.",
 boxes:[
  {e:"↪️", h:"Changing the subject", es:"Cambiar de tema", i:[["By the way, ...","Por cierto, ..."],["Speaking of which, ...","Hablando de eso, ..."],["Incidentally, ...","A propósito, ..."]], ex:["By the way, did you get my message?","Por cierto, ¿recibiste mi mensaje?"]},
  {e:"🔙", h:"Returning to a topic", es:"Retomar el tema", i:[["Anyway, as I was saying...","En fin, como decía..."],["Right, so...","Bien, entonces..."],["Back to the point...","Volviendo al tema..."]], ex:["Anyway, as I was saying, I'm moving house.","En fin, como decía, me mudo de casa."]},
  {e:"🤥", h:"Being honest", es:"Ser sincero", i:[["To be honest, ...","Para ser sincero, ..."],["Frankly, ...","Francamente, ..."],["To tell you the truth, ...","Si te soy sincero, ..."]], ex:["To be honest, I didn't like the film.","Para ser sincero, no me gustó la película."]},
  {e:"✨", h:"Actually & in fact", es:"Corregir o añadir", i:[["Actually, ...","En realidad, ... (corrige o sorprende)"],["As a matter of fact, ...","De hecho, ... (añade información)"],["In fact, ...","Es más, ... / en efecto, ..."]], ex:["As a matter of fact, I live in Bristol.","De hecho, vivo en Bristol."]},
  {e:"🤔", h:"Buying time", es:"Ganar tiempo", i:[["Well, ...","Bueno, ..."],["Let me think...","Déjame pensar..."],["You know, ...","Ya sabes, ..."]], ex:["Well, let me think about that for a moment.","Bueno, déjame pensarlo un momento."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["actually ≠ actualmente","'actually' = en realidad"],["Don't overuse 'like' and 'you know'","No abuses de 'like' ni 'you know'"],["Anyway ≠ any way","'anyway' va junto"]], ex:["Actually, I'm not working today.","En realidad, hoy no trabajo."]}
 ], qs:[
  {q:"Fill the gap: '____, did you hear about Tom?' (By the way / At the end)", a:"By the way — introduce un tema nuevo."},
  {q:"Choose the best reply to 'Did you enjoy the match?' – (a) 'To be honest, it was a bit dull.' (b) 'Honest to be it was dull.'", a:"(a) — 'To be honest' introduce una opinión sincera."},
  {q:"Rewrite to return to the topic: 'I'm continuing what I said.' (Anyway, ...)", a:"Anyway, as I was saying... — retoma el hilo."}
 ]},
{ cat:"Communication & British Culture", type:"Expressions", lvl:"B2", icon:"🪶", t:"Hedging & Softening", es:"Suavizar lo que decimos", d:"I tend to think, sort of, it seems that, a bit: decir las cosas sin sonar brusco.",
 boxes:[
  {e:"🧸", h:"Softening opinions", es:"Suavizar opiniones", i:[["I tend to think...","Tiendo a pensar..."],["I'd say...","Yo diría que..."],["I'm inclined to think...","Me inclino a pensar..."]], ex:["I tend to think it's too expensive.","Tiendo a pensar que es demasiado caro."]},
  {e:"🌫️", h:"Vague language", es:"Lenguaje impreciso", i:[["sort of / kind of","algo así / como que"],["a bit / a little","un poco"],["or so / or something","o así / o algo"]], ex:["It's sort of a café and sort of a bookshop.","Es como una cafetería y como una librería."]},
  {e:"👀", h:"Reporting appearances", es:"Apariencias", i:[["It seems that...","Parece que..."],["It appears to be...","Parece ser..."],["Apparently, ...","Al parecer, ..."]], ex:["It seems that the meeting has been cancelled.","Parece que han cancelado la reunión."]},
  {e:"📉", h:"Modals & probability", es:"Verbos modales", i:[["It might / could be...","Podría ser..."],["That may be true.","Puede que sea cierto."],["It's probably...","Probablemente es..."]], ex:["It could be a bit late by then.","Podría ser un poco tarde para entonces."]},
  {e:"🙏", h:"Softening criticism", es:"Suavizar críticas", i:[["It's not quite what I expected.","No es exactamente lo que esperaba."],["It's a bit on the pricey side.","Es algo caro."],["I'm not entirely convinced.","No estoy del todo convencido."]], ex:["I'm not entirely convinced by the plan.","No estoy del todo convencido con el plan."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores frecuentes", i:[["quite = fairly (UK), not 'totally'","'quite' = bastante (a veces moderado)"],["Too many hedges sound unsure","Demasiados suavizantes suenan inseguros"],["a bit + adjective / a bit of a + noun","un poco + adjetivo / un poco de + sustantivo"]], ex:["It's quite good, but a bit long.","Es bastante bueno, pero un poco largo."]}
 ], qs:[
  {q:"Fill the gap: 'It ____ that the shop is closed.' (seems / looks to)", a:"seems — 'It seems that...' = parece que."},
  {q:"Choose the more tactful sentence: (a) 'Your essay is bad.' (b) 'It's a bit on the short side, I'd say.'", a:"(b) — hedging suaviza la crítica."},
  {q:"Rewrite softer: 'This is wrong.' (I'm not ... sure ...)", a:"I'm not entirely sure this is right. — suavizado británico."}
 ]}
]);
